const nums = [4, 8, 15, 16, 23, 42];

// Современный JS: методы вместо циклов
const doubled = nums.map(n => n * 2);
const big = nums.filter(n => n > 15);
const total = nums.reduce((sum, n) => sum + n, 0);

console.log('map:', doubled);
console.log('filter:', big);
console.log('reduce:', total);

// Классическая функция
function add(a, b) {
  return a + b;
}

// Стрелочная — короче, особенно для однострочников
const multiply = (a, b) => a * b;      // return подразумевается
const square = n => n * n;             // одна скобка не нужна

console.log(add(2, 3), multiply(2, 3), square(5));

